import java.io.*;

public class Main {
    static final long MOD = 998244353L;

    static long[] multiply(long[] a, long[] b) {
        long[] result = new long[a.length + b.length - 1];
        for (int i = 0; i < a.length; i++) {
            if (a[i] == 0) continue;
            for (int j = 0; j < b.length; j++) {
                if (b[j] == 0) continue;
                result[i + j] = (result[i + j] + a[i] * b[j]) % MOD;
            }
        }
        return result;
    }

    static long[] combine(long[] a, long aScale, long[] b, long bScale,
                          long[] c, long cScale) {
        int size = Math.max(a.length, Math.max(b.length, c.length));
        long[] result = new long[size];
        for (int i = 0; i < size; i++) {
            long value = 0;
            if (i < a.length) value = (value + aScale * a[i]) % MOD;
            if (i < b.length) value = (value + bScale * b[i]) % MOD;
            if (i < c.length) value = (value + cScale * c[i]) % MOD;
            result[i] = value;
        }
        return result;
    }

    static long[] substituteSquare(long[] p) {
        long[] result = new long[2 * p.length - 1];
        for (int i = 0; i < p.length; i++) {
            result[2 * i] = p[i];
        }
        return result;
    }

    static long[] subtractShifted(long[] a, long[] b, int shift) {
        int size = Math.max(a.length, b.length + shift);
        long[] result = new long[size];
        System.arraycopy(a, 0, result, 0, a.length);
        for (int i = 0; i < b.length; i++) {
            int index = i + shift;
            result[index] -= b[i];
            if (result[index] < 0) result[index] += MOD;
        }
        return result;
    }

    static long[] subtractShiftedFrom(long[] a, long[] b, int shift) {
        int size = Math.max(a.length, b.length + shift);
        long[] result = new long[size];
        System.arraycopy(a, 0, result, 0, a.length);
        for (int i = 0; i < b.length; i++) {
            int index = i + shift;
            result[index] -= b[i];
            if (result[index] < 0) result[index] += MOD;
        }
        return result;
    }

    static long logarithmicCoefficient(long[] polynomial, int n) {
        long[] r = new long[n + 1];

        for (int m = 1; m <= n; m++) {
            long value = 0;
            if (m < polynomial.length) {
                value = (m * polynomial[m]) % MOD;
            }

            int limit = Math.min(m - 1, polynomial.length - 1);
            for (int i = 1; i <= limit; i++) {
                value -= polynomial[i] * r[m - i] % MOD;
                if (value < 0) value += MOD;
            }
            r[m] = value;
        }
        return r[n];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        long[] B = {1, MOD - 1, MOD - 1}; // 1 - y - y^2
        long[] B2 = multiply(B, B);
        long[] B3 = multiply(B2, B);

        long[] yOnePlusTwoY = {0, 1, 2};
        long[] U = multiply(yOnePlusTwoY, B);

        long[] R = {0, 1, 5, 3, 4};

        long[] NA = combine(R, 4, new long[0], 0, new long[0], 0);
        long[] NC = combine(R, 4, U, 4, B2, 1);
        long[] NE = combine(R, 4, U, 8, B2, 4);

        long[] denX = substituteSquare(B3);
        long[] naX = substituteSquare(NA);
        long[] ncX = substituteSquare(NC);
        long[] neX = substituteSquare(NE);

        long[] first = subtractShifted(denX, naX, 1);
        long[] second = subtractShifted(denX, neX, 3);

        long[] numerator = multiply(first, second);
        long[] ncSquared = multiply(ncX, ncX);
        long[] K = subtractShiftedFrom(numerator, ncSquared, 4);

        long denLog = logarithmicCoefficient(denX, n);
        long kLog = logarithmicCoefficient(K, n);

        long answer = (2 * denLog - kLog) % MOD;
        if (answer < 0) answer += MOD;

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}

import java.io.*;

public class Main {
    static final long MOD = 998244353L;

    static long[][] multiply(long[][] a, long[][] b) {
        int n = a.length;
        long[][] c = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                long aik = a[i][k];
                for (int j = 0; j < n; j++) {
                    if (b[k][j] == 0) continue;
                    c[i][j] = (c[i][j] + aik * b[k][j]) % MOD;
                }
            }
        }
        return c;
    }

    static long[][] power(long[][] base, int exponent) {
        int n = base.length;
        long[][] result = new long[n][n];
        for (int i = 0; i < n; i++) result[i][i] = 1;

        while (exponent > 0) {
            if ((exponent & 1) != 0) result = multiply(result, base);
            base = multiply(base, base);
            exponent >>= 1;
        }
        return result;
    }

    static long trace(long[][] matrix) {
        long result = 0;
        for (int i = 0; i < matrix.length; i++) {
            result += matrix[i][i];
            if (result >= MOD) result -= MOD;
        }
        return result;
    }

    static void addBlock(long[][] transfer, int from, int to, long[][] block) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int row = from * 3 + i;
                int col = to * 3 + j;
                transfer[row][col] += block[i][j];
                if (transfer[row][col] >= MOD) transfer[row][col] -= MOD;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        long[][] nonOpposite = {
            {1, 1, 0},
            {0, 1, 1},
            {0, 0, 1}
        };

        long[][] opposite = {
            {0, 0, 0},
            {0, 0, 0},
            {2, 1, 0}
        };

        long[][] transfer = new long[12][12];
        long[][] noOppositeTransfer = new long[4][4];

        for (int state = 0; state < 4; state++) {
            int currentOccupied = state & 1;
            int nextOccupied = (state >> 1) & 1;

            if (currentOccupied == 1) {
                int nextState = nextOccupied;
                addBlock(transfer, state, nextState, nonOpposite);
                noOppositeTransfer[state][nextState]++;
            } else {
                int monomerState = nextOccupied;
                addBlock(transfer, state, monomerState, opposite);

                if (nextOccupied == 0) {
                    int nextState = 1;
                    addBlock(transfer, state, nextState, nonOpposite);
                    noOppositeTransfer[state][nextState]++;
                }

                int nextState = nextOccupied | 2;
                addBlock(transfer, state, nextState, nonOpposite);
                noOppositeTransfer[state][nextState]++;
            }
        }

        long total = trace(power(transfer, n));
        long withoutOpposites = trace(power(noOppositeTransfer, n));

        long answer = (total - 3L * withoutOpposites) % MOD;
        if (answer < 0) answer += MOD;

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static long[][] multiply(long[][] a, long[][] b) {
        int n = a.length;
        long[][] c = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    if (b[k][j] == 0) continue;
                    c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
                }
            }
        }
        return c;
    }

    static long[][] power(long[][] a, int exponent) {
        int n = a.length;
        long[][] result = new long[n][n];
        for (int i = 0; i < n; i++) result[i][i] = 1;

        while (exponent > 0) {
            if ((exponent & 1) != 0) result = multiply(result, a);
            a = multiply(a, a);
            exponent >>= 1;
        }
        return result;
    }

    static long trace(long[][] matrix) {
        long result = 0;
        for (int i = 0; i < matrix.length; i++) {
            result += matrix[i][i];
            if (result >= MOD) result -= MOD;
        }
        return result;
    }

    static void addBlock(long[][] matrix, int toMask, int fromMask, long[][] block) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int row = toMask * 3 + i;
                int col = fromMask * 3 + j;
                matrix[row][col] += block[i][j];
                if (matrix[row][col] >= MOD) matrix[row][col] -= MOD;
            }
        }
    }

    static void addTransition(long[][] matrix, int to, int from) {
        matrix[to][from]++;
        if (matrix[to][from] == MOD) matrix[to][from] = 0;
    }

    static long solveLarge(int n) {
        long[][] increment = {
                {1, 0, 0},
                {1, 1, 0},
                {1, 2, 1}
        };

        long[][] closeGap = {
                {0, 0, 1},
                {0, 0, 0},
                {0, 0, 0}
        };

        long[][] transfer = new long[12][12];
        long[][] noMonomer = new long[4][4];

        for (int mask = 0; mask < 4; mask++) {
            int currentOccupied = mask & 1;
            int nextOccupied = (mask >> 1) & 1;

            if (currentOccupied != 0) {
                int nextMask = nextOccupied;
                addBlock(transfer, nextMask, mask, increment);
                addTransition(noMonomer, nextMask, mask);
            } else {
                int monomerMask = nextOccupied;
                addBlock(transfer, monomerMask, mask, closeGap);

                if (nextOccupied == 0) {
                    int edgeOneMask = 1;
                    addBlock(transfer, edgeOneMask, mask, increment);
                    addTransition(noMonomer, edgeOneMask, mask);
                }

                int edgeTwoMask = nextOccupied | 2;
                addBlock(transfer, edgeTwoMask, mask, increment);
                addTransition(noMonomer, edgeTwoMask, mask);
            }
        }

        long weighted = trace(power(transfer, n));
        long perfectDimers = trace(power(noMonomer, n));

        long answer = (weighted - 3L * perfectDimers) % MOD;
        if (answer < 0) answer += MOD;
        return answer;
    }

    static int smallN;
    static boolean[] covered;
    static boolean[] singleton;
    static int[] edgeA;
    static int[] edgeB;
    static long smallAnswer;

    static void bruteForce(int coveredCount) {
        if (coveredCount == smallN) {
            int singletonCount = 0;
            for (boolean value : singleton) {
                if (value) singletonCount++;
            }
            if (singletonCount == 0) return;

            long product = 1;
            for (int i = 0; i < smallN; i++) {
                if (!singleton[i]) continue;
                int gap = 0;
                int j = (i + 1) % smallN;
                while (!singleton[j]) {
                    gap++;
                    j = (j + 1) % smallN;
                }
                product = product * gap % MOD;
            }

            smallAnswer = (smallAnswer + product * product) % MOD;
            return;
        }

        int v = 0;
        while (covered[v]) v++;

        covered[v] = true;
        singleton[v] = true;
        bruteForce(coveredCount + 1);
        singleton[v] = false;
        covered[v] = false;

        for (int e = 0; e < edgeA.length; e++) {
            int other;
            if (edgeA[e] == v) {
                other = edgeB[e];
            } else if (edgeB[e] == v) {
                other = edgeA[e];
            } else {
                continue;
            }

            if (!covered[other]) {
                covered[v] = true;
                covered[other] = true;
                bruteForce(coveredCount + 2);
                covered[v] = false;
                covered[other] = false;
            }
        }
    }

    static long solveSmall(int n) {
        smallN = n;
        covered = new boolean[n];
        singleton = new boolean[n];
        edgeA = new int[2 * n];
        edgeB = new int[2 * n];

        int index = 0;
        for (int i = 0; i < n; i++) {
            for (int distance = 1; distance <= 2; distance++) {
                edgeA[index] = i;
                edgeB[index] = (i + distance) % n;
                index++;
            }
        }

        smallAnswer = 0;
        bruteForce(0);
        return smallAnswer;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine().trim());
        long answer = n <= 4 ? solveSmall(n) : solveLarge(n);
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static long[] multiply(long[] a, long[] b) {
        long[] c = new long[a.length + b.length - 1];
        for (int i = 0; i < a.length; i++) {
            if (a[i] == 0) continue;
            for (int j = 0; j < b.length; j++) {
                c[i + j] = (c[i + j] + a[i] * b[j]) % MOD;
            }
        }
        return c;
    }

    static long[] subtract(long[] a, long[] b) {
        int size = Math.max(a.length, b.length);
        long[] c = new long[size];
        for (int i = 0; i < size; i++) {
            long x = i < a.length ? a[i] : 0;
            long y = i < b.length ? b[i] : 0;
            c[i] = (x - y + MOD) % MOD;
        }
        return c;
    }

    static long[] scale(long[] a, long factor) {
        long[] b = new long[a.length];
        for (int i = 0; i < a.length; i++) {
            b[i] = a[i] * factor % MOD;
        }
        return b;
    }

    static long[] shift(long[] a, int amount) {
        long[] b = new long[a.length + amount];
        System.arraycopy(a, 0, b, amount, a.length);
        return b;
    }

    static long[] derivative(long[] a) {
        if (a.length <= 1) return new long[]{0};
        long[] b = new long[a.length - 1];
        for (int i = 1; i < a.length; i++) {
            b[i - 1] = a[i] * i % MOD;
        }
        return b;
    }

    static long[] thetaSquaredNumerator(int k, long[] q, long[] qPrime) {
        long[] r = new long[k + 1];
        r[k] = 1;

        long[] rPrime = derivative(r);
        long[] first = subtract(multiply(rPrime, q), multiply(r, qPrime));
        long[] b = shift(first, 1);

        long[] second = subtract(
                multiply(derivative(b), q),
                scale(multiply(b, qPrime), 2)
        );
        return shift(second, 1);
    }

    static long logCoefficient(long[] h, int n, long[] inverse) {
        long[] c = new long[n + 1];

        for (int m = 1; m <= n; m++) {
            long value = 0;
            if (m < h.length) {
                value = h[m] * m % MOD;
            }

            int limit = Math.min(m - 1, h.length - 1);
            for (int i = 1; i <= limit; i++) {
                long term = h[i] * (m - i) % MOD * c[m - i] % MOD;
                value -= term;
                if (value < 0) value += MOD;
            }

            c[m] = value * inverse[m] % MOD;
        }
        return c[n];
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        long[] q = {1, 0, MOD - 1, 0, MOD - 1};
        long[] qPrime = derivative(q);

        long[] a0 = thetaSquaredNumerator(0, q, qPrime);
        long[] a1 = thetaSquaredNumerator(1, q, qPrime);
        long[] a2 = thetaSquaredNumerator(2, q, qPrime);

        long[] q2 = multiply(q, q);
        long[] q3 = multiply(q2, q);

        long[] u0 = subtract(q3, shift(a0, 1));
        long[] u2 = subtract(q3, shift(a2, 1));

        long[] p = subtract(
                multiply(u0, u2),
                shift(multiply(a1, a1), 2)
        );

        long[] inverse = new long[n + 1];
        inverse[1] = 1;
        for (int i = 2; i <= n; i++) {
            inverse[i] = (MOD - (MOD / i) * inverse[(int) (MOD % i)] % MOD) % MOD;
        }

        long logP = logCoefficient(p, n, inverse);
        long logQ = logCoefficient(q, n, inverse);

        long coefficient = (6 * logQ - logP) % MOD;
        if (coefficient < 0) coefficient += MOD;

        long answer = coefficient * n % MOD;
        System.out.println(answer);
    }
}

import java.io.*;

public class Main {
    static final long MOD = 998244353L;

    static long[][] multiply(long[][] a, long[][] b) {
        int n = a.length;
        long[][] c = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                long x = a[i][k];
                for (int j = 0; j < n; j++) {
                    if (b[k][j] == 0) continue;
                    c[i][j] = (c[i][j] + x * b[k][j]) % MOD;
                }
            }
        }
        return c;
    }

    static long[][] power(long[][] base, long exp) {
        int n = base.length;
        long[][] result = new long[n][n];
        for (int i = 0; i < n; i++) result[i][i] = 1;

        while (exp > 0) {
            if ((exp & 1) != 0) result = multiply(result, base);
            base = multiply(base, base);
            exp >>= 1;
        }
        return result;
    }

    static void addLabel(long[][] matrix, int fromMask, int toMask, long[][] label) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int from = fromMask * 3 + i;
                int to = toMask * 3 + j;
                matrix[from][to] = (matrix[from][to] + label[i][j]) % MOD;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        long[][] covered = {
            {1, 0, 0},
            {1, 1, 0},
            {1, 2, 1}
        };

        long[][] monomer = new long[3][3];
        monomer[0][2] = 1;

        long[][] transition = new long[12][12];
        long[][] perfectTransition = new long[4][4];

        for (int mask = 0; mask < 4; mask++) {
            int shifted = mask >> 1;

            if ((mask & 1) != 0) {
                addLabel(transition, mask, shifted, covered);
                perfectTransition[mask][shifted]++;
            } else {
                addLabel(transition, mask, shifted, monomer);

                if ((mask & 2) == 0) {
                    int next = shifted | 1;
                    addLabel(transition, mask, next, covered);
                    perfectTransition[mask][next]++;
                }

                int next = shifted | 2;
                addLabel(transition, mask, next, covered);
                perfectTransition[mask][next]++;
            }
        }

        long[][] totalPower = power(transition, n);
        long total = 0;
        for (int i = 0; i < 12; i++) {
            total = (total + totalPower[i][i]) % MOD;
