        long[][] perfectPower = power(perfectTransition, n);
        long perfect = 0;
        for (int i = 0; i < 4; i++) {
            perfect = (perfect + perfectPower[i][i]) % MOD;
        }

        long answer = (total - 3L * perfect) % MOD;
        if (answer < 0) answer += MOD;

        System.out.println(answer);
    }

